from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse
from fastapi.templating import Jinja2Templates
from pathlib import Path
from ..database import execute_query

router = APIRouter(prefix="/audit-logs", tags=["audit-logs"])
templates = Jinja2Templates(directory=str(Path(__file__).resolve().parent.parent / "templates"))


@router.get("", response_class=HTMLResponse)
async def list_audit_logs(
    request: Request,
    table_name: str = None,
    action_type: str = None
):
    """View chronological audit trail generated by database triggers and procedures."""
    conditions = []
    params = {}

    if table_name and table_name != "ALL":
        conditions.append("table_name = :tname")
        params["tname"] = table_name
    if action_type and action_type != "ALL":
        conditions.append("action_type = :atype")
        params["atype"] = action_type

    where_clause = "WHERE " + " AND ".join(conditions) if conditions else ""

    sql = f"""
        SELECT log_id, account_id, table_name, action_type,
               TO_CHAR(action_time, 'YYYY-MM-DD HH24:MI:SS') AS action_time,
               details
        FROM audit_log
        {where_clause}
        ORDER BY log_id DESC
    """
    logs = execute_query(sql, params)

    # Tables and action types for dropdown filter
    tables = execute_query("SELECT DISTINCT table_name FROM audit_log ORDER BY table_name ASC")
    actions = execute_query("SELECT DISTINCT action_type FROM audit_log ORDER BY action_type ASC")

    return templates.TemplateResponse(request=request, name="audit_logs.html", context={
        "request": request,
        "logs": logs,
        "tables": [t["table_name"] for t in tables],
        "actions": [a["action_type"] for a in actions],
        "selected_table": table_name or "ALL",
        "selected_action": action_type or "ALL"
    })
